select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,
  'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'required',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
  'constraints',(select jsonb_agg(jsonb_build_object('name',x.conname,'definition',pg_get_constraintdef(x.oid,true)) order by x.conname) from pg_constraint x where x.conrelid=c.oid),
  'acl',(select jsonb_agg(jsonb_build_object('role',coalesce(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable) order by coalesce(r.rolname,'PUBLIC'),a.privilege_type) from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a left join pg_roles r on r.oid=a.grantee)) order by n.nspname,c.relname)
  from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('finance','ops','telegram_private') and c.relkind in('r','p')),
 'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'returns',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'volatility',p.provolatile,'strict',p.proisstrict,'source',md5(replace(p.prosrc,E'\r\n',E'\n')),
  'acl',(select jsonb_agg(jsonb_build_object('role',coalesce(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable) order by coalesce(r.rolname,'PUBLIC'),a.privilege_type) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a left join pg_roles r on r.oid=a.grantee)) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','finance','ops','telegram_private')),
 'policies',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'cmd',cmd,'using',qual,'check',with_check) order by schemaname,tablename,policyname) from pg_policies where schemaname in('finance','ops','telegram_private') or (schemaname='storage' and policyname like 'category_images_%')),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in('finance','ops','telegram_private')),
 'indexes',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',indexname,'definition',indexdef) order by schemaname,tablename,indexname) from pg_indexes where schemaname in('finance','ops','telegram_private')),
 'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'login',rolcanlogin,'super',rolsuper,'inherit',rolinherit,'bypass',rolbypassrls,'create_role',rolcreaterole,'create_db',rolcreatedb,'replication',rolreplication) order by rolname) from pg_roles where rolname in('app_executor','finzi_deletion_worker','finzi_deletion_gateway','finzi_telegram_gateway','finzi_telegram_transport_executor')),
 'memberships',(select coalesce(jsonb_agg(jsonb_build_object('member',mbr.rolname,'role',r.rolname,'admin',m.admin_option) order by mbr.rolname,r.rolname),'[]'::jsonb) from pg_auth_members m join pg_roles r on r.oid=m.roleid join pg_roles mbr on mbr.oid=m.member where mbr.rolname in('app_executor','finzi_deletion_worker','finzi_deletion_gateway','finzi_telegram_gateway','finzi_telegram_transport_executor'))
) as catalog;
